import{c as t,S as d,j as o,m as a}from"./chunks/framework.DBSVVeOL.js";const y=JSON.parse('{"title":"Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference.md","filePath":"reference.md","lastUpdated":null}'),r={name:"reference.md"};function l(c,e,s,n,i,u){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="Reference" tabindex="-1">Reference <a class="header-anchor" href="#Reference" aria-label="Permalink to &quot;Reference {#Reference}&quot;">​</a></h1><p>This page summarizes the public API. Optional keyword defaults are documented in the guide pages when behavior matters. Timeout keyword values are positive finite seconds.</p><h2 id="Core-Types" tabindex="-1">Core Types <a class="header-anchor" href="#Core-Types" aria-label="Permalink to &quot;Core Types {#Core-Types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>Client</code></td><td style="text-align:left;">Active client connection with background reader, ping, and reconnect tasks.</td></tr><tr><td style="text-align:left;"><code>ConnectOptions</code></td><td style="text-align:left;">Immutable keyword-backed connection configuration, including typed authentication, TLS verification and server-name control, reconnect, buffering, write timeout, parser, subscription, and close callback limits.</td></tr><tr><td style="text-align:left;"><code>ConnectionStatus</code></td><td style="text-align:left;">EnumX status namespace: <code>DISCONNECTED</code>, <code>CONNECTING</code>, <code>CONNECTED</code>, <code>RECONNECTING</code>, <code>DRAINING</code>, <code>CLOSED</code>.</td></tr><tr><td style="text-align:left;"><code>ConnectionEventKind</code></td><td style="text-align:left;">EnumX event namespace: <code>CONNECTED</code>, <code>DISCONNECTED</code>, <code>RECONNECT_ATTEMPT</code>, <code>RECONNECT_DELAY</code>, <code>RECONNECTED</code>, <code>DISCOVERED_SERVERS</code>, <code>TERMINAL_DISCONNECT</code>, <code>CLOSED</code>.</td></tr><tr><td style="text-align:left;"><code>ConnectionEvent</code></td><td style="text-align:left;">Lifecycle event passed to <code>event_cb</code>, with status, server, URL, attempt, delay, error, and generation fields.</td></tr><tr><td style="text-align:left;"><code>NoAuth</code>, <code>TokenAuth</code>, <code>UserPassAuth</code>, <code>NKeyAuth</code>, <code>JwtAuth</code>, <code>CredentialsAuth</code>, <code>CallbackAuth</code></td><td style="text-align:left;">Typed connection authentication values passed as <code>auth=...</code> to <code>connect</code> or <code>ConnectOptions</code>.</td></tr><tr><td style="text-align:left;"><code>AuthRequest</code></td><td style="text-align:left;">Context passed to <code>CallbackAuth</code>, including server, URL, nonce, INFO, attempt, and reconnect flag.</td></tr><tr><td style="text-align:left;"><code>NatterTask</code></td><td style="text-align:left;">Explicit async operation handle. Use <code>fetch(handle)</code> when code intentionally starts an operation and joins it later. Failed handles throw the same operation error that the synchronous API would throw.</td></tr><tr><td style="text-align:left;"><code>Msg</code></td><td style="text-align:left;">Core received message data with <code>subject</code>, <code>reply</code>, and byte-vector <code>data</code>; use <code>header(msg, key)</code> or <code>headers(msg)</code> for headers.</td></tr><tr><td style="text-align:left;"><code>Headers</code></td><td style="text-align:left;">Case-insensitive dictionary of header names to <code>Vector{String}</code> values; publish and request APIs also accept dictionaries with string or vector values and pair iterators. Outbound header names must be valid NATS/HTTP token field names. Mixed-case duplicates are merged under one entry, with the first inserted field spelling used for iteration and serialization.</td></tr><tr><td style="text-align:left;"><code>PublishFrame</code></td><td style="text-align:left;">Validated, immutable prepared core publish frame. Use <code>prepare_publish</code> when the same subject, reply, headers, and payload are published repeatedly on a hot path.</td></tr><tr><td style="text-align:left;"><code>Subscription</code></td><td style="text-align:left;">Core subscription handle.</td></tr><tr><td style="text-align:left;"><code>Stats</code></td><td style="text-align:left;">Snapshot of message, byte, reconnect, error, and drop counters.</td></tr></tbody></table><h2 id="Core-Functions" tabindex="-1">Core Functions <a class="header-anchor" href="#Core-Functions" aria-label="Permalink to &quot;Core Functions {#Core-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>connect(url_or_urls=nothing; kwargs...)</code></td><td style="text-align:left;">Connect to one or more servers.</td></tr><tr><td style="text-align:left;"><code>publish(client, subject, data=nothing; reply=nothing, headers=nothing)</code></td><td style="text-align:left;">Publish a core message; header publishes require server INFO header support. Reconnect replay is best-effort and can duplicate retained frames after ambiguous transport failures.</td></tr><tr><td style="text-align:left;"><code>prepare_publish(subject, data=nothing; reply=nothing, headers=nothing)</code></td><td style="text-align:left;">Validate and serialize publish metadata once, returning a <code>PublishFrame</code> for repeated <code>publish(client, frame)</code> calls.</td></tr><tr><td style="text-align:left;"><code>publish(client, frame::PublishFrame)</code></td><td style="text-align:left;">Publish a prepared frame without repeating subject, reply, payload, or header serialization work. Server capability and size checks still run against the active client.</td></tr><tr><td style="text-align:left;"><code>subscribe(client, subject; queue=nothing, callback=nothing, max_msgs=0, ...)</code></td><td style="text-align:left;">Create a core subscription; positive <code>max_msgs</code> closes after that many total messages. Per-subscription pending limits must be positive.</td></tr><tr><td style="text-align:left;"><code>next(sub; timeout=1.0)</code></td><td style="text-align:left;">Wait for the next message from a non-callback subscription.</td></tr><tr><td style="text-align:left;"><code>request(client, subject, data=nothing; timeout=1.0, headers=nothing)</code></td><td style="text-align:left;">Send a request and wait for one response; request headers require server INFO header support.</td></tr><tr><td style="text-align:left;"><code>flush(client; timeout=10.0)</code></td><td style="text-align:left;">Wait until the server has processed previous commands.</td></tr><tr><td style="text-align:left;"><code>ping(client; timeout=10.0)</code></td><td style="text-align:left;">Alias for <code>flush</code>.</td></tr><tr><td style="text-align:left;"><code>unsubscribe(sub; max_msgs=0)</code></td><td style="text-align:left;">Unsubscribe immediately or after <code>max_msgs</code> additional messages. <code>max_msgs</code> must be non-negative.</td></tr><tr><td style="text-align:left;"><code>drain(sub; timeout=...)</code></td><td style="text-align:left;">Unsubscribe and wait for queued callback work within one deadline.</td></tr><tr><td style="text-align:left;"><code>drain(client; timeout=...)</code></td><td style="text-align:left;">Drain subscriptions and flush within one shared deadline, then close the client.</td></tr><tr><td style="text-align:left;"><code>close(client; throw_errors=false, callback_timeout=nothing)</code></td><td style="text-align:left;">Close transports, tasks, and subscriptions. Active callbacks are waited on without interruption for <code>callback_timeout</code> or <code>close_callback_timeout</code>.</td></tr><tr><td style="text-align:left;"><code>new_inbox(client; prefix=...)</code></td><td style="text-align:left;">Generate a reply inbox subject.</td></tr><tr><td style="text-align:left;"><code>header(msg, key)</code></td><td style="text-align:left;">Return the first header value by case-insensitive key lookup or <code>nothing</code>.</td></tr><tr><td style="text-align:left;"><code>headers(msg)</code></td><td style="text-align:left;">Return a copy of all message headers.</td></tr><tr><td style="text-align:left;"><code>status(client)</code></td><td style="text-align:left;">Return current <code>ConnectionStatus</code>.</td></tr><tr><td style="text-align:left;"><code>stats(client)</code></td><td style="text-align:left;">Return a <code>Stats</code> snapshot.</td></tr><tr><td style="text-align:left;"><code>connected_url(client)</code></td><td style="text-align:left;">Return the current server URL or <code>nothing</code>.</td></tr></tbody></table><h2 id="Core-Task-Handle-Helpers" tabindex="-1">Core Task Handle Helpers <a class="header-anchor" href="#Core-Task-Handle-Helpers" aria-label="Permalink to &quot;Core Task Handle Helpers {#Core-Task-Handle-Helpers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>connect_async(url_or_urls=nothing; kwargs...)</code></td><td style="text-align:left;">Start <code>connect</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>publish_async(client, subject, data=nothing; kwargs...)</code></td><td style="text-align:left;">Start core <code>publish</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>publish_async(client, frame::PublishFrame)</code></td><td style="text-align:left;">Start prepared-frame publish and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>subscribe_async(client, subject; kwargs...)</code></td><td style="text-align:left;">Start <code>subscribe</code> and return <code>NatterTask</code>; callback-first style is supported.</td></tr><tr><td style="text-align:left;"><code>next_async(sub; timeout=1.0)</code></td><td style="text-align:left;">Start <code>next</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>request_async(client, subject, data=nothing; kwargs...)</code></td><td style="text-align:left;">Start <code>request</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>flush_async(client; timeout=10.0)</code></td><td style="text-align:left;">Start <code>flush</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>ping_async(client; timeout=10.0)</code></td><td style="text-align:left;">Start <code>ping</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>unsubscribe_async(sub; max_msgs=0)</code></td><td style="text-align:left;">Start <code>unsubscribe</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>drain_async(client_or_sub; timeout=...)</code></td><td style="text-align:left;">Start <code>drain</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>close_async(client_or_sub_or_watcher; kwargs...)</code></td><td style="text-align:left;">Start <code>close</code> and return <code>NatterTask</code>.</td></tr></tbody></table><h2 id="JetStream-Types" tabindex="-1">JetStream Types <a class="header-anchor" href="#JetStream-Types" aria-label="Permalink to &quot;JetStream Types {#JetStream-Types}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Type</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>JetStreamContext</code></td><td style="text-align:left;">JetStream API context for a client.</td></tr><tr><td style="text-align:left;"><code>StreamConfig</code></td><td style="text-align:left;">Typed stream configuration with local subject, name, and numeric validation. Raw <code>Dict</code> configs use the same seconds-based duration conversion for known stream fields.</td></tr><tr><td style="text-align:left;"><code>ConsumerConfig</code></td><td style="text-align:left;">Typed consumer configuration with local subject, name, queue, and numeric validation. Raw <code>Dict</code> configs use the same seconds-based duration conversion for known consumer fields.</td></tr><tr><td style="text-align:left;"><code>StreamLostData</code></td><td style="text-align:left;">Typed lost-message summary nested under stream state.</td></tr><tr><td style="text-align:left;"><code>StreamState</code></td><td style="text-align:left;">Typed stream state counters, sequence bounds, subjects, deletion, and lost-data summary.</td></tr><tr><td style="text-align:left;"><code>StreamInfo</code></td><td style="text-align:left;">Stream info response with typed config and typed state.</td></tr><tr><td style="text-align:left;"><code>ConsumerSequenceInfo</code></td><td style="text-align:left;">Typed consumer/stream sequence cursor in consumer info responses.</td></tr><tr><td style="text-align:left;"><code>ConsumerInfo</code></td><td style="text-align:left;">Consumer info response with typed config, counters, sequence cursors, and push-bound state.</td></tr><tr><td style="text-align:left;"><code>PubAck</code></td><td style="text-align:left;">Publish acknowledgement with stream, sequence, duplicate, and domain.</td></tr><tr><td style="text-align:left;"><code>JetStreamMsg</code></td><td style="text-align:left;">JetStream consumer message data plus acknowledgement state for <code>ack</code>, <code>nak</code>, <code>in_progress</code>, and <code>term</code>.</td></tr><tr><td style="text-align:left;"><code>PullSubscription</code></td><td style="text-align:left;">Pull consumer handle.</td></tr><tr><td style="text-align:left;"><code>PushSubscription</code></td><td style="text-align:left;">Push consumer handle.</td></tr></tbody></table><h2 id="JetStream-Enums" tabindex="-1">JetStream Enums <a class="header-anchor" href="#JetStream-Enums" aria-label="Permalink to &quot;JetStream Enums {#JetStream-Enums}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Enum Namespace</th><th style="text-align:left;">Values</th></tr></thead><tbody><tr><td style="text-align:left;"><code>RetentionPolicy</code></td><td style="text-align:left;"><code>LIMITS</code>, <code>INTEREST</code>, <code>WORK_QUEUE</code></td></tr><tr><td style="text-align:left;"><code>StorageType</code></td><td style="text-align:left;"><code>FILE</code>, <code>MEMORY</code></td></tr><tr><td style="text-align:left;"><code>DiscardPolicy</code></td><td style="text-align:left;"><code>OLD</code>, <code>NEW</code></td></tr><tr><td style="text-align:left;"><code>StoreCompression</code></td><td style="text-align:left;"><code>NONE</code>, <code>S2</code></td></tr><tr><td style="text-align:left;"><code>PersistMode</code></td><td style="text-align:left;"><code>DEFAULT</code>, <code>ASYNC</code></td></tr><tr><td style="text-align:left;"><code>AckPolicy</code></td><td style="text-align:left;"><code>NONE</code>, <code>ALL</code>, <code>EXPLICIT</code></td></tr><tr><td style="text-align:left;"><code>DeliverPolicy</code></td><td style="text-align:left;"><code>ALL</code>, <code>LAST</code>, <code>NEW</code>, <code>BY_START_SEQUENCE</code>, <code>BY_START_TIME</code>, <code>LAST_PER_SUBJECT</code></td></tr><tr><td style="text-align:left;"><code>ReplayPolicy</code></td><td style="text-align:left;"><code>INSTANT</code>, <code>ORIGINAL</code></td></tr><tr><td style="text-align:left;"><code>PriorityPolicy</code></td><td style="text-align:left;"><code>NONE</code>, <code>OVERFLOW</code>, <code>PINNED_CLIENT</code></td></tr></tbody></table><h2 id="JetStream-Functions" tabindex="-1">JetStream Functions <a class="header-anchor" href="#JetStream-Functions" aria-label="Permalink to &quot;JetStream Functions {#JetStream-Functions}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>jetstream(client; prefix=&quot;$JS.API&quot;, timeout=5.0)</code></td><td style="text-align:left;">Create a JetStream context.</td></tr><tr><td style="text-align:left;"><code>js_publish(js, subject, data=nothing; timeout=..., stream=nothing, headers=nothing, msg_id=nothing, expected_last_sequence=nothing, expected_last_subject_sequence=nothing, expected_last_subject=nothing, expected_last_msg_id=nothing, ttl=nothing, schedule=nothing, schedule_at=nothing, schedule_every=nothing, retry_attempts=0, retry_wait=0.25)</code></td><td style="text-align:left;">Publish and wait for a <code>PubAck</code>; first-class options map to JetStream publish headers. Use <code>msg_id</code> with the stream duplicate window to suppress duplicate publishes caused by reconnect or retry ambiguity.</td></tr><tr><td style="text-align:left;"><code>js_publish_async(js, subject, data=nothing; kwargs...)</code></td><td style="text-align:left;">Start <code>js_publish</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>publish_async(js, subject, data=nothing; kwargs...)</code></td><td style="text-align:left;">Alias for <code>js_publish_async</code>.</td></tr><tr><td style="text-align:left;"><code>stream_create(js, config)</code></td><td style="text-align:left;">Create a stream from <code>StreamConfig</code> or <code>Dict</code>.</td></tr><tr><td style="text-align:left;"><code>stream_update(js, config)</code></td><td style="text-align:left;">Update a stream.</td></tr><tr><td style="text-align:left;"><code>stream_info(js, name)</code></td><td style="text-align:left;">Fetch stream info.</td></tr><tr><td style="text-align:left;"><code>stream_list(js; offset=0)</code></td><td style="text-align:left;">List streams, following pagination.</td></tr><tr><td style="text-align:left;"><code>stream_names(js; subject=nothing)</code></td><td style="text-align:left;">List stream names, optionally filtered by subject.</td></tr><tr><td style="text-align:left;"><code>stream_purge(js, name; filter_subject=nothing, keep=nothing)</code></td><td style="text-align:left;">Purge a stream or subject subset, optionally keeping recent messages.</td></tr><tr><td style="text-align:left;"><code>stream_delete(js, name)</code></td><td style="text-align:left;">Delete a stream.</td></tr><tr><td style="text-align:left;"><code>stream_message_get(js, stream; seq=nothing, subject=nothing, direct=false, next_by_subject=false)</code></td><td style="text-align:left;">Read a stored message. Sequence lookups require a positive sequence.</td></tr><tr><td style="text-align:left;"><code>stream_message_delete(js, stream, seq)</code></td><td style="text-align:left;">Delete one stored message by positive sequence.</td></tr><tr><td style="text-align:left;"><code>consumer_create(js, stream, config)</code></td><td style="text-align:left;">Strictly create a consumer from <code>ConsumerConfig</code> or <code>Dict</code>.</td></tr><tr><td style="text-align:left;"><code>consumer_create_or_update(js, stream, config)</code></td><td style="text-align:left;">Explicitly create or update a consumer.</td></tr><tr><td style="text-align:left;"><code>consumer_update(js, stream, config)</code></td><td style="text-align:left;">Strictly update an existing consumer.</td></tr><tr><td style="text-align:left;"><code>consumer_info(js, stream, consumer)</code></td><td style="text-align:left;">Fetch consumer info.</td></tr><tr><td style="text-align:left;"><code>consumer_list(js, stream; offset=0)</code></td><td style="text-align:left;">List consumers for a stream.</td></tr><tr><td style="text-align:left;"><code>consumer_delete(js, stream, consumer)</code></td><td style="text-align:left;">Delete a consumer.</td></tr><tr><td style="text-align:left;"><code>pull_subscribe(js, subject; stream=nothing, durable=nothing, config=ConsumerConfig(), timeout=...)</code></td><td style="text-align:left;">Create or bind a pull subscription without mutating existing consumers. Configs with <code>deliver_subject</code> or <code>deliver_group</code> are rejected because they describe push delivery.</td></tr><tr><td style="text-align:left;"><code>push_subscribe(js, subject; stream=nothing, durable=nothing, queue=nothing, callback=nothing, manual_ack=false, config=ConsumerConfig(), timeout=...)</code></td><td style="text-align:left;">Create or bind a push subscription without mutating existing consumers. Existing queue consumers require an explicit matching <code>queue</code>. Callback subscriptions receive <code>JetStreamMsg</code> and auto-ack unless <code>manual_ack=true</code> or the consumer uses <code>AckPolicy.NONE</code>; channel-backed subscriptions use <code>next(psub)</code> for <code>JetStreamMsg</code> delivery.</td></tr><tr><td style="text-align:left;"><code>fetch(psub, batch=1; timeout=..., expires=&lt;shorter than timeout&gt;, heartbeat=nothing, max_bytes=nothing, no_wait=false, min_pending=nothing, min_ack_pending=nothing, priority_group=nothing, priority=nothing)</code></td><td style="text-align:left;">Fetch a bounded batch of <code>JetStreamMsg</code> values. <code>max_bytes</code> adds a server byte cap, and <code>no_wait=true</code> returns immediately with currently available messages. Fetches on one subscription are serialized, use unique reply subjects, ignore stale terminal statuses, and are not replayed after reconnect.</td></tr><tr><td style="text-align:left;"><code>messages(psub; batch=100, max_bytes=nothing, expires=30.0, heartbeat=nothing, threshold_messages=nothing, threshold_bytes=nothing, channel_size=batch, stop_after=nothing, min_pending=nothing, min_ack_pending=nothing, priority_group=nothing, priority=nothing)</code></td><td style="text-align:left;">Start a threshold-refilled pull message stream and return <code>PullMessageStream</code>. Refill thresholds are based on messages and bytes buffered or already requested for the client. The stream supports iteration, <code>take!</code>, <code>wait</code>, <code>fetch</code>, and <code>close</code>. Only one active fetch or stream may use a pull subscription at a time.</td></tr><tr><td style="text-align:left;"><code>consume(callback, psub; kwargs...)</code></td><td style="text-align:left;">Start a callback worker on top of <code>messages</code>. The returned <code>PullMessageStream</code> controls shutdown and error propagation.</td></tr><tr><td style="text-align:left;"><code>ack</code>, <code>ack_sync</code>, <code>nak</code>, <code>in_progress</code>, <code>term</code></td><td style="text-align:left;">Acknowledge or control redelivery for <code>JetStreamMsg</code> values. Terminal acks are not queued during reconnect and remain retryable if the send fails.</td></tr><tr><td style="text-align:left;"><code>metadata(msg)</code></td><td style="text-align:left;">Parse JetStream delivery metadata.</td></tr></tbody></table><h2 id="JetStream-Task-Handle-Helpers" tabindex="-1">JetStream Task Handle Helpers <a class="header-anchor" href="#JetStream-Task-Handle-Helpers" aria-label="Permalink to &quot;JetStream Task Handle Helpers {#JetStream-Task-Handle-Helpers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>stream_create_async(js, config)</code></td><td style="text-align:left;">Start <code>stream_create</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>stream_update_async(js, config)</code></td><td style="text-align:left;">Start <code>stream_update</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>stream_info_async(js, name)</code></td><td style="text-align:left;">Start <code>stream_info</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>stream_list_async(js; offset=0)</code></td><td style="text-align:left;">Start <code>stream_list</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>stream_names_async(js; subject=nothing)</code></td><td style="text-align:left;">Start <code>stream_names</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>stream_purge_async(js, name; filter_subject=nothing, keep=nothing)</code></td><td style="text-align:left;">Start <code>stream_purge</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>stream_delete_async(js, name)</code></td><td style="text-align:left;">Start <code>stream_delete</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>stream_message_get_async(js, stream; kwargs...)</code></td><td style="text-align:left;">Start <code>stream_message_get</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>stream_message_delete_async(js, stream, seq)</code></td><td style="text-align:left;">Start <code>stream_message_delete</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>consumer_create_async(js, stream, config)</code></td><td style="text-align:left;">Start <code>consumer_create</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>consumer_create_or_update_async(js, stream, config)</code></td><td style="text-align:left;">Start <code>consumer_create_or_update</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>consumer_update_async(js, stream, config)</code></td><td style="text-align:left;">Start <code>consumer_update</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>consumer_info_async(js, stream, consumer)</code></td><td style="text-align:left;">Start <code>consumer_info</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>consumer_list_async(js, stream; offset=0)</code></td><td style="text-align:left;">Start <code>consumer_list</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>consumer_delete_async(js, stream, consumer)</code></td><td style="text-align:left;">Start <code>consumer_delete</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>pull_subscribe_async(js, subject; kwargs...)</code></td><td style="text-align:left;">Start <code>pull_subscribe</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>push_subscribe_async(js, subject; kwargs...)</code></td><td style="text-align:left;">Start <code>push_subscribe</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>fetch_async(psub, batch=1; kwargs...)</code></td><td style="text-align:left;">Start pull <code>fetch</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>ack_async</code>, <code>ack_sync_async</code>, <code>nak_async</code>, <code>in_progress_async</code>, <code>term_async</code></td><td style="text-align:left;">Start <code>JetStreamMsg</code> acknowledgement operations and return <code>NatterTask</code>.</td></tr></tbody></table><h2 id="KeyValue-Functions" tabindex="-1">KeyValue Functions <a class="header-anchor" href="#KeyValue-Functions" aria-label="Permalink to &quot;KeyValue Functions {#KeyValue-Functions}&quot;">​</a></h2><p><code>KeyValueEntry</code> contains <code>bucket</code>, <code>key</code>, <code>value</code>, <code>revision</code>, <code>created</code>, <code>delta</code>, and <code>operation</code>. <code>operation</code> uses the <code>KeyValueOperation</code> enum namespace: <code>PUT</code>, <code>DELETE</code>, and <code>PURGE</code>. <code>KeyValueStatus</code> contains <code>bucket</code>, <code>stream</code>, <code>values</code>, <code>history</code>, <code>ttl</code>, <code>bytes</code>, <code>storage</code>, <code>replicas</code>, <code>direct</code>, and the backing <code>stream_info</code>. <code>KeyValueWatcher</code> wraps a push subscription. Channel-backed watchers yield <code>KeyValueEntry</code> values and the <code>KV_WATCH_INITIAL_DONE</code> sentinel.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>kv_create(js, bucket; history=1, ttl=nothing, max_bytes=-1, max_value_size=-1, storage=&quot;file&quot;, replicas=1, direct=false, compression=nothing, metadata=nothing, limit_marker_ttl=nothing, timeout=...)</code></td><td style="text-align:left;">Create a bucket. Durations are seconds; <code>history</code> is limited to 1 through 64.</td></tr><tr><td style="text-align:left;"><code>kv_open(js, bucket; timeout=...)</code></td><td style="text-align:left;">Open an existing bucket.</td></tr><tr><td style="text-align:left;"><code>kv_delete_bucket(kv; timeout=...)</code></td><td style="text-align:left;">Delete a bucket.</td></tr><tr><td style="text-align:left;"><code>kv_status(kv; timeout=...)</code></td><td style="text-align:left;">Return bucket status and stream-backed configuration.</td></tr><tr><td style="text-align:left;"><code>kv_get(kv, key; revision=nothing, direct=nothing, timeout=...)</code></td><td style="text-align:left;">Get the latest value or a revision as <code>KeyValueEntry</code>.</td></tr><tr><td style="text-align:left;"><code>kv_put(kv, key, value; revision=nothing, ttl=nothing, timeout=...)</code></td><td style="text-align:left;">Put a value, optionally expecting a revision or setting a per-key TTL; returns the new revision.</td></tr><tr><td style="text-align:left;"><code>kv_create_key(kv, key, value; ttl=nothing, timeout=...)</code></td><td style="text-align:left;">Put a value only if the key is absent or currently deleted; returns the new revision.</td></tr><tr><td style="text-align:left;"><code>kv_update(kv, key, value, revision; ttl=nothing, timeout=...)</code></td><td style="text-align:left;">Put a value only if the key is at <code>revision</code>; returns the new revision.</td></tr><tr><td style="text-align:left;"><code>kv_delete(kv, key; revision=nothing, timeout=...)</code></td><td style="text-align:left;">Mark a key deleted, optionally only if the key is at <code>revision</code>.</td></tr><tr><td style="text-align:left;"><code>kv_purge(kv, key; revision=nothing, ttl=nothing, timeout=...)</code></td><td style="text-align:left;">Purge a key with rollup, optionally only if the key is at <code>revision</code>; <code>ttl</code> expires the purge marker.</td></tr><tr><td style="text-align:left;"><code>kv_purge_deletes(kv; older_than=1800.0, timeout=...)</code></td><td style="text-align:left;">Remove delete and purge markers, keeping recent markers when <code>older_than</code> is positive.</td></tr><tr><td style="text-align:left;"><code>kv_history(kv, key; batch=256, timeout=...)</code></td><td style="text-align:left;">Return historical <code>KeyValueEntry</code> values for a key.</td></tr><tr><td style="text-align:left;"><code>kv_keys(kv; timeout=...)</code></td><td style="text-align:left;">Return active keys.</td></tr><tr><td style="text-align:left;"><code>kv_watch(kv; key=&quot;&gt;&quot;, keys=nothing, history=false, updates_only=false, ignore_deletes=false, meta_only=false, resume_revision=nothing, timeout=...)</code></td><td style="text-align:left;">Watch bucket updates with a <code>KeyValueWatcher</code> and sentinel channel.</td></tr><tr><td style="text-align:left;"><code>kv_watch(callback, kv; kwargs...)</code></td><td style="text-align:left;">Watch bucket updates with a callback.</td></tr></tbody></table><h2 id="KeyValue-Task-Handle-Helpers" tabindex="-1">KeyValue Task Handle Helpers <a class="header-anchor" href="#KeyValue-Task-Handle-Helpers" aria-label="Permalink to &quot;KeyValue Task Handle Helpers {#KeyValue-Task-Handle-Helpers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Function</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>kv_create_async(js, bucket; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_create</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_open_async(js, bucket; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_open</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_delete_bucket_async(kv; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_delete_bucket</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_status_async(kv; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_status</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_get_async(kv, key; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_get</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_put_async(kv, key, value; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_put</code> and return <code>NatterTask</code>; <code>fetch</code> returns the new revision.</td></tr><tr><td style="text-align:left;"><code>kv_create_key_async(kv, key, value; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_create_key</code> and return <code>NatterTask</code>; <code>fetch</code> returns the new revision.</td></tr><tr><td style="text-align:left;"><code>kv_update_async(kv, key, value, revision; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_update</code> and return <code>NatterTask</code>; <code>fetch</code> returns the new revision.</td></tr><tr><td style="text-align:left;"><code>kv_delete_async(kv, key; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_delete</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_purge_async(kv, key; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_purge</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_purge_deletes_async(kv; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_purge_deletes</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_history_async(kv, key; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_history</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_keys_async(kv; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_keys</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>kv_watch_async(kv; kwargs...)</code>, <code>kv_watch_async(callback, kv; kwargs...)</code></td><td style="text-align:left;">Start <code>kv_watch</code> and return <code>NatterTask</code>.</td></tr><tr><td style="text-align:left;"><code>close_async(watcher::KeyValueWatcher)</code></td><td style="text-align:left;">Close a key-value watcher in a <code>NatterTask</code>.</td></tr></tbody></table><h2 id="Errors" tabindex="-1">Errors <a class="header-anchor" href="#Errors" aria-label="Permalink to &quot;Errors {#Errors}&quot;">​</a></h2><p>Public error types derive from <code>NatterError</code>: <code>TimeoutError</code>, <code>NoRespondersError</code>, <code>ConnectionClosedError</code>, <code>ConnectionReconnectingError</code>, <code>ConnectionDrainingError</code>, <code>ProtocolError</code>, <code>AuthenticationError</code>, <code>AuthorizationError</code>, <code>AuthenticationExpiredError</code>, <code>AuthenticationRevokedError</code>, <code>AccountAuthenticationExpiredError</code>, <code>PermissionViolationError</code>, <code>NoServersError</code>, <code>MaxPayloadError</code>, <code>OutboundBufferLimitError</code>, <code>SlowConsumerError</code>, <code>JetStreamError</code>, <code>FetchDisconnectedError</code>, <code>KeyValueError</code>, <code>UnsupportedFeatureError</code>, and <code>CleanupError</code>.</p><p>KeyValue-specific errors derive from <code>KeyValueError</code>: <code>KeyValueKeyNotFoundError</code>, <code>KeyValueKeyDeletedError</code>, <code>KeyValueWrongRevisionError</code>, and <code>KeyValueKeyExistsError</code>.</p>',24)])])}const f=t(r,[["render",l]]);export{y as __pageData,f as default};
